import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"UGSo Special","description":"Lignes SVG animées et nœuds de sommation pour ioBroker VIS 2.","frontmatter":{"title":"UGSo Special","description":"Lignes SVG animées et nœuds de sommation pour ioBroker VIS 2."},"headers":[],"relativePath":"fr/iobroker/widgets/ugso-spezial/index.md","filePath":"fr/iobroker/widgets/ugso-spezial/index.md","lastUpdated":1794506345000}'),r={name:"fr/iobroker/widgets/ugso-spezial/index.md"};function n(o,e,l,u,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="ugso-special" tabindex="-1">UGSo Special <a class="header-anchor" href="#ugso-special" aria-label="Permalink to &quot;UGSo Special&quot;">​</a></h1><p><strong>UGSo Special</strong> permet de visualiser des flux de données dans VIS 2, par exemple la puissance de plusieurs appareils. Le pack contient deux widgets.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><ul><li><strong>SVG-Line</strong> relie des points par un tracé droit, à angle droit ou passant par des points intermédiaires. Les couleurs, les longueurs des tirets et les pointes de flèche sont réglables. Une valeur positive anime la ligne vers l’avant, une valeur négative inverse le sens et une valeur nulle arrête l’animation. La vitesse peut être fixe ou proportionnelle à la valeur absolue.</li><li><strong>SVG LineBox</strong> additionne jusqu’à quatre entrées et une valeur de correction facultative. Le total peut être transmis à deux lignes de sortie au maximum ou écrit, dans la vue d’exécution, dans un état numérique existant et modifiable sous <code>0_userdata.0</code>. Si une entrée sélectionnée est indisponible, le nœud attend sa valeur.</li></ul><p>Dans l’éditeur, faites glisser une extrémité jaune pour l’aimanter à une autre ligne ou à une LineBox. Une extrémité munie d’une flèche ne peut pas s’aimanter. L’aimantation aligne le dessin ; le transfert des valeurs se configure séparément dans la LineBox.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="preparation-du-catalogue-0-1-34" tabindex="-1">Préparation du catalogue 0.1.34 <a class="header-anchor" href="#preparation-du-catalogue-0-1-34" aria-label="Permalink to &quot;Préparation du catalogue 0.1.34&quot;">​</a></h3><p>Cette version comprend des notes de version dans les onze langues du catalogue, des dépendances corrigées, une analyse statique automatisée et les contrôles de paquet ioBroker. Les publications utilisent GitHub Actions avec une attestation de provenance npm. bluefox figure parmi les copropriétaires npm. L’admission au catalogue officiel reste en cours ; les fonctions des widgets et les projets existants sont conservés.</p><p>Le paquet s’appelle désormais <code>iobroker.vis-2-widgets-ugso-special</code>. Exportez vos projets VIS 2 pour les sauvegarder, installez le nouveau paquet et redémarrez VIS 2. Vérifiez les projets avant de supprimer l’ancien paquet. Les identifiants des modèles de widgets et le nom interne de fédération sont conservés.</p><p>Une installation VIS 2 opérationnelle est nécessaire. Installez le pack via son URL GitHub dans ioBroker Admin (mode expert). Après une mise à jour, redémarrez VIS 2 pour charger la nouvelle version. Les deux widgets figurent dans la palette de l’éditeur sous <strong>UGSo Special</strong>.</p><ul><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-special" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-special/releases" target="_blank" rel="noreferrer">Releases</a></li><li><a href="https://www.npmjs.com/package/iobroker.vis-2-widgets-ugso-special" target="_blank" rel="noreferrer">npm</a></li></ul>',11)])])}const m=a(r,[["render",n]]);export{g as __pageData,m as default};
